def fiscal_quarter(month, fiscal_start_month):
    offset = (month - fiscal_start_month) % 12
    return offset // 3 + 1

def count_specific_weekday_in_range(start_day_num, end_day_num, weekday):
    count = 0
    for d in range(start_day_num, end_day_num + 1):
        if d % 7 == weekday:
            count += 1
    return count

def is_coprime(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a == 1

def longest_positive_run_sum(lst):
    best_len = 0
    best_sum = 0
    cur_len = 0
    cur_sum = 0
    for x in lst:
        if x > 0:
            cur_len += 1
            cur_sum += x
        else:
            if cur_len > best_len:
                best_len = cur_len
                best_sum = cur_sum
            cur_len = 0
            cur_sum = 0
    if cur_len > best_len:
        best_sum = cur_sum
    return best_sum

def count_letter_digit_symbol_groups(s):
    def cls(c):
        if c.isalpha():
            return 'L'
        if c.isdigit():
            return 'D'
        return 'O'
    if not s:
        return 0
    count = 1
    for i in range(1, len(s)):
        if cls(s[i]) != cls(s[i - 1]):
            count += 1
    return count

def top_unique_score_names(records, k):
    first_name = {}
    for name, score in records:
        if score not in first_name:
            first_name[score] = name
    scores_sorted = sorted(first_name.keys(), reverse=True)
    return [first_name[s] for s in scores_sorted[:k]]

def average_across_dicts_zero_fill(dicts_list):
    n = len(dicts_list)
    if n == 0:
        return {}
    all_keys = set()
    for d in dicts_list:
        all_keys.update(d.keys())
    return {k: round(sum(d.get(k, 0) for d in dicts_list) / n, 2) for k in all_keys}

def group_by_first_element(pairs):
    result = {}
    for a, b in pairs:
        result.setdefault(a, []).append(b)
    return result

def election_winner(votes):
    counts = {}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    best = max(counts.values())
    cands = [k for k, c in counts.items() if c == best]
    return min(cands)

def count_char_bigrams(s):
    counts = {}
    for i in range(len(s) - 1):
        bg = s[i] + s[i + 1]
        counts[bg] = counts.get(bg, 0) + 1
    return counts

def sliding_window_max(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [max(lst[i:i+k]) for i in range(len(lst) - k + 1)]

def cube_root_floor(n):
    lo, hi = 0, max(1, n)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def is_palindrome_in_base(n, base):
    digits = []
    x = n
    if x == 0:
        digits = [0]
    while x > 0:
        digits.append(x % base)
        x //= base
    return digits == digits[::-1]

def cumulative_counts(items):
    seen = {}
    res = []
    for x in items:
        seen[x] = seen.get(x, 0) + 1
        res.append(seen[x])
    return res

def last_occurrence_indices(seq):
    result = {}
    for i, x in enumerate(seq):
        result[x] = i
    return result

def meets_min_digit_count_policy(s):
    if any(c.isspace() for c in s):
        return False
    if not (6 <= len(s) <= 20):
        return False
    return sum(c.isdigit() for c in s) >= 2

def highest_peak_index(lst):
    peaks = [i for i in range(1, len(lst) - 1) if lst[i] > lst[i - 1] and lst[i] > lst[i + 1]]
    if not peaks:
        return -1
    best = peaks[0]
    for i in peaks:
        if lst[i] > lst[best]:
            best = i
    return best

def group_ages_into_brackets(ages):
    from collections import defaultdict
    groups = defaultdict(list)
    for a in ages:
        b = (a // 10) * 10
        groups[b].append(a)
    return {f"{b}-{b+9}": sorted(groups[b]) for b in sorted(groups)}

def is_valid_card_display_format(s):
    groups = s.split(' ')
    if len(groups) != 4:
        return False
    for g in groups:
        if g == 'XXXX':
            continue
        if len(g) == 4 and g.isdigit():
            continue
        return False
    return True

def is_valid_roman_numeral(s):
    import re
    if not s:
        return False
    pattern = r'M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})'
    return re.fullmatch(pattern, s) is not None

def xor_of_range(a, b):
    def f(x):
        if x < 0:
            return 0
        m = x % 4
        if m == 0:
            return x
        if m == 1:
            return 1
        if m == 2:
            return x + 1
        return 0
    return f(b) ^ f(a - 1)

def is_alternating_case(s):
    letters = [c for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        if letters[i].isupper() == letters[i - 1].isupper():
            return False
    return True

def is_valid_spreadsheet_cell(s):
    import re
    return bool(re.fullmatch(r'[A-Z]{1,2}[1-9]\d*', s))

def is_valid_binary_fraction(s):
    parts = s.split('.')
    if len(parts) != 2:
        return False
    int_part, frac_part = parts
    if not int_part or not frac_part:
        return False
    return all(c in '01' for c in int_part) and all(c in '01' for c in frac_part)

def sort_by_consonant_count(words):
    vowels = set('aeiouAEIOU')
    def ccount(w):
        return sum(1 for c in w if c.isalpha() and c not in vowels)
    return sorted(words, key=lambda w: (-ccount(w), w))

def previous_day(date):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    y, m, d = date
    if d > 1:
        return (y, m, d-1)
    m -= 1
    if m < 1:
        return (y-1, 12, 31)
    return (y, m, dim(y, m))

def next_leap_year(year):
    y = year + 1
    while not (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)):
        y += 1
    return y

def custom_fibonacci(a, b, n):
    if n == 0:
        return a
    if n == 1:
        return b
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def nested_group_counts(pairs):
    res = {}
    for g, item in pairs:
        res.setdefault(g, {})
        res[g][item] = res[g].get(item, 0) + 1
    return res

def shift_left_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return lst[n:] + [fill] * n
